const introMain=document.querySelector('.intro-hero');const introBody=document.querySelector('.intro-content');if(introMain&&introBody){introMain.innerHTML='<div class="intro-hero-copy"><div class="official-badge">CHÍNH THỨC ĐƯỢC BỘ GIÁO DỤC &amp; ĐÀO TẠO CÔNG NHẬN</div><h1>Oxford Test of English</h1><h2>Được công nhận tương đương Khung năng lực ngoại ngữ 6 bậc dùng cho Việt Nam</h2><p>Theo <strong>Quyết định số 1429/QĐ-BGDĐT ngày 29/05/2026</strong>, Bộ Giáo dục và Đào tạo công nhận các cấp độ của chứng chỉ <strong>Oxford Test of English (OTE)</strong> và <strong>OTE Advanced</strong> tương đương với các bậc của Khung năng lực ngoại ngữ 6 bậc dùng cho Việt Nam, để sử dụng trong tuyển sinh và đào tạo các trình độ của giáo dục đại học.</p><div class="hero-buttons left"><a class="primary" href="#quy-doi">Xem bảng quy đổi OTE</a><button class="secondary consult-trigger" type="button">Đăng ký dự thi</button></div></div><div class="decision-mockup"><div class="decision-paper"><small>BỘ GIÁO DỤC VÀ ĐÀO TẠO</small><strong>QUYẾT ĐỊNH<br>1429/QĐ-BGDĐT</strong><span>29/05/2026</span></div><div class="score-card"><small>Oxford Test of English</small><strong>CEFR Result</strong><b>B2</b></div></div>';introBody.innerHTML='<section id="quy-doi" class="conversion"><div class="eyebrow">BẢNG QUY ĐỔI</div><h2>OTE được quy đổi như thế nào?</h2><p>Mức điểm được Bộ GD&amp;ĐT công nhận theo Quyết định 1429/QĐ-BGDĐT</p><div class="conversion-table"><table><thead><tr><th>Khung NLNN 6 bậc Việt Nam</th><th>Oxford Test of English</th><th>OTE Advanced</th></tr></thead><tbody><tr><th>Bậc 1</th><td>21 – 50</td><td>—</td></tr><tr><th>Bậc 2</th><td>51 – 80</td><td>—</td></tr><tr><th>Bậc 3</th><td>81 – 110</td><td>—</td></tr><tr><th>Bậc 4</th><td>111 – 140</td><td>111 – 140</td></tr><tr><th>Bậc 5</th><td>—</td><td>141 – 170</td></tr></tbody></table></div><p class="decision-note">Đây là các khoảng điểm được nêu tại Điều 1 của Quyết định.</p><div class="choice-callout"><div><strong>Bạn cần Bậc 3, Bậc 4 hay Bậc 5?</strong><span>Xác định bài thi OTE phù hợp với yêu cầu của trường hoặc chương trình đào tạo của bạn.</span></div><button class="primary consult-trigger" type="button">Tư vấn lựa chọn bài thi →</button></div></section>' ;document.querySelectorAll('.consult-trigger').forEach(x=>x.addEventListener('click',()=>document.querySelector('.nav-cta')?.click()))}
